const { useState } = React;

function Product() {
  const [product, setProduct] = useState({
    name: '파란 셔츠',
    price: 39000,
    stock: 5,
  });

  function raisePrice() {
    setProduct((previous) => ({
      ...previous,
      price: previous.price + 1000,
    }));
  }

  return (
    <section>
      <p>{product.name}: {product.price}원 / 재고 {product.stock}</p>
      <button type="button" onClick={raisePrice}>가격 올리기</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Product />);

